<script>(function(){
var _cs = document.currentScript;
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
var margin = {left:62, top:18, right:24, bottom:46};
var PW = 594, PH = 300 - margin.top - margin.bottom;
var data = [70.44,73.52,72.08,71.41,77.94,78.68,79.12,78.28,81.78,82.48,84.34,83.64,87.01,85.15,82.61,79.26,84.46,83.59,84.67,80.34,75.77,75.22,77.99,77.93];
var dLabels = ["7 juill.","8 juill.","9 juill.","10 juill.","13 juill.","14 juill.","15 juill.","16 juill.","17 juill.","20 juill.","21 juill.","22 juill.","23 juill.","24 juill.","27 juill.","28 juill.","29 juill.","30 juill.","31 juill.","3 août","4 août","5 août","6 août","7 août"];
var n = data.length;
var yMin = 66, yMax = 90;
function xp(i){ return margin.left + (i/(n-1)) * PW; }
function yp(v){ return margin.top + PH - ((v - yMin)/(yMax - yMin)) * PH; }

var yTicks = [70,75,80,85,90];
yTicks.forEach(function(gv){
  var gy = yp(gv);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","fill":"#aaaaaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, gv+"\u00a0$"));
});

var refValue = 75;
var refY = yp(refValue);
var currentVal = data[n-1];
if (Math.abs(refValue - currentVal) / currentVal >= 0.03) {
  svg.appendChild(el("text",{x:margin.left+140,y:refY-10,"text-anchor":"start","font-size":"7","fill":"#7a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "BASE PRÉ-ACCORD ~75\u00a0$"));
}
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#7a3030","stroke-dasharray":"3,3"}));

var pathD = "";
data.forEach(function(v,i){
  var x = xp(i), y = yp(v);
  pathD += (i===0 ? "M" : "L") + x + "," + y + " ";
});
svg.appendChild(el("path",{d:pathD, fill:"none", stroke:"#4a5568", "stroke-width":"2"}));

svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
var labelIdx = [0,4,8,12,16,20,23];
labelIdx.forEach(function(i){
  svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":"8","fill":"#999999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, dLabels[i]));
});

var events = [
  {i:12, label:"SOMMET ESCALADE"},
  {i:20, label:"MANCHETTES DE L\u2019ACCORD"}
];
events.forEach(function(ev){
  var ex = xp(ev.i);
  var ey = yp(data[ev.i]);
  svg.appendChild(el("line",{x1:ex,x2:ex,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
  var labelWidth = ev.label.length * 7 * 0.68;
  var crowded = events.some(function(other){ return other.i !== ev.i && Math.abs(xp(other.i) - ex) < 85; });
  var nearRight = (ex + labelWidth + 3) > (margin.left + PW);
  var offset = (crowded || nearRight) ? -6 : 3;
  var yStart = crowded ? margin.top + 50 : margin.top + 20;
  var anchor = (crowded || nearRight) ? "end" : "start";
  svg.appendChild(el("text",{x:ex+offset,y:yStart,"text-anchor":anchor,"font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, ev.label));
