<script>(function(){
var _cs = document.currentScript;
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
var margin = {left:62, top:18, right:24, bottom:46};
var PW = 594, PH = 300 - margin.top - margin.bottom;
var months = ["janv. 25","févr. 25","mars 25","avr. 25","mai 25","juin 25","juill. 25","août 25","sept. 25","oct. 25","nov. 25","déc. 25","janv. 26","févr. 26","mars 26","avr. 26","mai 26","juin 26","juill. 26","août 26"];
var boc = [3.0,3.0,2.75,2.75,2.75,2.75,2.75,2.75,2.5,2.25,2.25,2.25,2.25,2.25,2.25,2.25,2.25,2.25,2.25,2.25];
var fed = [4.375,4.375,4.375,4.375,4.375,4.375,4.375,4.375,4.125,3.875,3.875,3.625,3.625,3.625,3.625,3.625,3.625,3.625,3.625,3.625];
var n = months.length;
var yMin = 2.0, yMax = 4.75;
function xp(i){ return margin.left + (i/(n-1)) * PW; }
function yp(v){ return margin.top + PH - ((v - yMin)/(yMax - yMin)) * PH; }

var yTicks = [2.0,2.5,3.0,3.5,4.0,4.5];
yTicks.forEach(function(gv){
  var gy = yp(gv);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","fill":"#aaaaaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, gv.toFixed(1).replace(".",",")+"\u00a0%"));
});

function stepPath(series){
  var d = "";
  for (var i=0;i<series.length;i++){
    var x = xp(i), y = yp(series[i]);
    if (i===0){ d += "M" + x + "," + y + " "; }
    else {
      var prevX = xp(i-1);
      d += "L" + x + "," + yp(series[i-1]) + " ";
      d += "L" + x + "," + y + " ";
    }
  }
  return d;
}
svg.appendChild(el("path",{d:stepPath(boc), fill:"none", stroke:"#4a5568", "stroke-width":"2"}));
svg.appendChild(el("path",{d:stepPath(fed), fill:"none", stroke:"#6b7280", "stroke-width":"2"}));

svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
var labelIdx = [0,4,8,12,16,19];
labelIdx.forEach(function(i){
  svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":"8","fill":"#999999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, months[i]));
});

var events = [
  {i:8, label:"DOUBLE BAISSE"},
  {i:15, label:"ADIEU DE POWELL"}
];
events.forEach(function(ev){
  var ex = xp(ev.i);
  svg.appendChild(el("line",{x1:ex,x2:ex,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
  var labelWidth = ev.label.length * 7 * 0.68;
  var crowded = events.some(function(other){ return other.i !== ev.i && Math.abs(xp(other.i) - ex) < 85; });
  var nearRight = (ex + labelWidth + 3) > (margin.left + PW);
  var offset = (crowded || nearRight) ? -40 : 3;
  var yStart = crowded ? margin.top + 50 : margin.top + 20;
  var anchor = (crowded || nearRight) ? "end" : "start";
  svg.appendChild(el("text",{x:ex+offset,y:yStart,"text-anchor":anchor,"font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, ev.label));
});

var labelYOffsets = [10, -6];
var lastX = xp(n-1);
var lastBocY = yp(boc[n-1]);
var lastFedY = yp(fed[n-1]);
svg.appendChild(el("circle",{cx:lastX,cy:lastBocY,r:4,fill:"#4a5568"}));
svg.appendChild(el("circle",{cx:lastX,cy:lastFedY,r:4,fill:"#6b7280"}));

svg.appendChild(el("text",{x:lastX-4,y:lastBocY+3+labelYOffsets[0],"text-anchor":"end","font-size":"7.5","fill":"#4a5568","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "BdC"));

var pillText = "FED 3,50-3,75\u00a0%";
var pillW = Math.ceil(pillText.length * 9 * 0.62) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastFedY - pillH/2 + labelYOffsets[1];
if (pillX < margin.left) pillX = margin.left;
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, pillText));

var legendBaseX = margin.left + 10;
var legendY = margin.top + 10;
svg.appendChild(el("rect",{x:legendBaseX,y:legendY-6,width:10,height:3,fill:"#4a5568"}));
svg.appendChild(el("text",{x:legendBaseX+14,y:legendY-2,"text-anchor":"start","font-size":"7.5","fill":"#444444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "Taux à un jour (BdC)"));
svg.appendChild(el("rect",{x:legendBaseX+110,y:legendY-6,width:10,height:3,fill:"#6b7280"}));
svg.appendChild(el("text",{x:legendBaseX+124,y:legendY-2,"text-anchor":"start","font-size":"7.5","fill":"#444444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "Taux des fonds fédéraux (médian)"));

_cs.parentNode.appendChild(svg);
})();</script>
