VALUES (
  '2026/08/07/hdq-fil-7-aout-2026',
  'thread', 'thread',
  'Le dollar canadien fait un mouvement dont le marché obligataire doute encore', 'Le USD/CAD est tombé à son plus bas niveau depuis juin sur la divergence de l’emploi, mais le rendement à 5 ans qui fixe les renouvellements a redonné l’essentiel de sa poussée en matinée, laissant deux marchés lire deux histoires différentes dans les mêmes données.',
  '',
  '<p>Deux rapports sur l’emploi sont tombés la même matinée de vendredi, et à la cloche de clôture, le marché s’était forgé une réponse claire quant à celui qui comptait le plus, du moins pour un actif. Le USD/CAD a reculé de 0,53 % à 1,3940, son plus bas niveau depuis juin, après que Statistique Canada a rapporté une hausse de l’emploi canadien de 75 100 en juillet contre une estimation du consensus d’environ 17 800, tandis que le Bureau of Labor Statistics des États-Unis a rapporté une perte de 23 000 emplois contre une hausse prévue de 83 000.</p>
<p>Le rendement des obligations du gouvernement du Canada à 5 ans, l’instrument qui détermine réellement un renouvellement hypothécaire, racontait une histoire plus modeste. Il a bondi jusqu’à 3,274 % en quelques minutes après la publication de 8 h 30, en hausse par rapport à la clôture de jeudi à 3,228 %, avant de redescendre vers environ 3,25 % plus tard en matinée, selon Canadian Mortgage Trends. Il s’agit d’un mouvement net d’environ deux points de base en fin de matinée, et non le point de base décrit par l’article du pupitre Fiscalité et patrimoine ce matin, et considérablement moins que ce que la réaction du marché des devises laisse croire quant à l’ampleur réelle du changement des perspectives politiques.</p>
L’écart entre le résultat canadien et le raté américain est comparé directement ci-dessous, calibré à leur écart par rapport au consensus plutôt qu’à leurs totaux bruts.
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">EMPLOI DE JUILLET, RÉEL C. CONSENSUS</span>
<span style="font-size:20px;font-weight:700;color:#111;">+75,1 k c. -23 k</span>
<span style="font-size:13px;color:#2e7d32;">▲ Canada devance de 4,2x</span>
<span style="font-size:11px;color:#888;margin-left:auto;">STATCAN &nbsp;|&nbsp; BLS, JUILLET 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>(function(){
  var _cs = document.currentScript;
  function el(tag, attrs, txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");

  var margin = {left:110, right:24, top:18, bottom:46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;

  var data = [
    {label:"Canada réel", v:75.1, group:"ca"},
    {label:"Canada, consensus", v:17.8, group:"ca"},
    {label:"États-Unis, réel", v:-23, group:"us"},
    {label:"États-Unis, consensus", v:83, group:"us"}
  ];

  var n = data.length;
  var maxAbs = 90;
  var zeroX = margin.left + PW * 0.42;

  var xScale = function(v){ return zeroX + (v / maxAbs) * (PW * 0.55); };

  var gap = 5;
  var barH = Math.floor((PH - (n-1)*gap) / n);
  if (barH > 40) barH = 40;

  svg.appendChild(el("line",{x1:zeroX,x2:zeroX,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

  for (var hi=0; hi<n-1; hi++){
    var hy = margin.top + (hi+1)*barH + hi*gap + gap/2;
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:hy,y2:hy,stroke:"#ececec","stroke-width":"0.5"}));
  }

  var pillIndex = 0;

  for (var i=0;i<n;i++){
    var d = data[i];
    var y = margin.top + i*(barH+gap);
    var isPos = d.v >= 0;
    var bx0 = isPos ? zeroX : xScale(d.v);
    var bx1 = isPos ? xScale(d.v) : zeroX;
    var w = Math.max(bx1 - bx0, 2);
    var isActual = d.label.indexOf("réel") !== -1;
    var fill = isActual ? (isPos ? "#3a7a55" : "#8a3030") : "#9ca3af";
    svg.appendChild(el("rect",{x:bx0,y:y,width:w,height:barH,fill:fill}));

    svg.appendChild(el("text",{x:margin.left-6,y:y+barH/2+3,"text-anchor":"end","font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#444444"}, d.label));

    var valText = (d.v>=0&&isActual&&d.group==="ca"?"+":"") + d.v.toFixed(1).replace(".",",") + "\u00a0k";

    if (i===pillIndex){
      var pillTextW = valText.length * 9 * 0.58;
      var pillW = Math.ceil(pillTextW) + 10;
      var pillH = 14;
      var pillX = isPos ? (bx1 + 4) : (bx0 - pillW - 4);
      if (pillX + pillW > margin.left + PW) pillX = margin.left + PW - pillW;
      if (pillX < margin.left) pillX = margin.left;
      var pillY = y + barH/2 - pillH/2;
      svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:2,fill:"#e8a825"}));
      svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+3,"text-anchor":"middle","font-size":"9","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"}, valText));
    } else {
      var lx = isPos ? bx1 + 6 : bx0 - 6;
      var anchorDir = isPos ? "start" : "end";
      svg.appendChild(el("text",{x:lx,y:y+barH/2+3,"text-anchor":anchorDir,"font-size":"8","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#444444"}, valText));
    }
  }

  svg.appendChild(el("text",{x:margin.left+PW-4,y:margin.top+PH+16,"text-anchor":"end","font-size":"7","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, "Milliers d\u2019emplois, juillet 2026"));

  _cs.parentNode.appendChild(svg);
})();</script>
